import type {Chapter,Example,Question,Task} from './types';
const ex=(title:string,code:string,output:string,why:string,input?:string):Example=>({title,code,output,why,input});
const q=(prompt:string,correct:string,wrong:string[],explanation:string):Question=>{const options=[...wrong];const answer=prompt.length%4;options.splice(answer,0,correct);return {prompt,options,answer,explanation};};
type TaskSeed=[string,string,string,string,string,string?];
function tasks(chapter:number,seeds:TaskSeed[]):Task[]{return seeds.map(([title,prompt,starter,solution,expected,tests],i)=>({id:`${chapter}-${i}`,chapter,title,difficulty:['Easy','Medium','Challenge'][i],prompt,starter,solution,expected,tests,hints:['Read the expected output carefully. Work out the result by hand first.',`Useful starting point: ${solution.split('\n')[0]}`],explanation:`${prompt} The solution processes the given values and produces ${JSON.stringify(expected)}. Try changing the values after passing the check.`}));}
const chapters:Chapter[]=[
{id:0,title:'Before Python',subtitle:'Understand what programming really is',story:'You ask a friend to make chai. “Make tea” leaves many decisions unanswered. A recipe with ordered steps is much clearer. Computers also need precise instructions, but cannot fill in missing meaning the way your friend can.',objectives:['Explain computers, programs and programming languages','Trace input → process → output','Arrange a simple algorithm in order'],concepts:[['Computer, program, programmer','A computer follows instructions to process information. A program is a set of instructions. Programming means designing those instructions, testing them, and improving them. A programmer spends time understanding problems, reading code, debugging, and communicating.'],['Why Python?','A programming language lets people express instructions in a form a computer can execute. Guido van Rossum created Python; its first public release was in 1991. He wanted an approachable language that made programming productive. It is used for automation, data analysis, websites, and scientific work.'],['Languages have different strengths','Python emphasizes readable code. JavaScript commonly adds interaction to web pages. C and C++ give more direct control over memory and systems. All can solve many kinds of problems; Python does not automatically understand ordinary English.'],['From source to output','Source code is the text you write. The Python interpreter processes it and executes instructions; internally it can compile to bytecode first. Output is a result, such as displayed text. Input → process → output is a useful model, though some programs have no input or run continuously.']],visual:['Input: milk, water, tea','Process: follow the recipe','Output: a cup of chai'],examples:[ex('Instructions in order','print("Boil water")\nprint("Add tea")\nprint("Serve")','Boil water\nAdd tea\nServe','Statements run from top to bottom. Printing a step describes it; this code does not actually boil water.'),ex('Input → process → output','cups = 3\nprice = 10\nprint(cups * price)','30','Three cups at ₹10 each cost ₹30. The asterisk means multiplication.')],mistake:{code:'print("Serve")\nprint("Boil water")',fix:'print("Boil water")\nprint("Serve")',why:'Code can run without an error and still have the wrong order. Logical mistakes require checking meaning.'},application:'A shop billing program receives quantities, calculates a total, and displays a bill. Start by writing its steps in plain language.',tasks:tasks(0,[['Order the recipe','Print Boil water, Add tea, Serve on separate lines in that order.','# Write three steps','print("Boil water")\nprint("Add tea")\nprint("Serve")','Boil water\nAdd tea\nServe'],['Process a bill','Print the cost of 4 cups at ₹10 each.','cups = 4\nprice = 10','cups = 4\nprice = 10\nprint(cups * price)','40'],['Plan attendance','There are 30 students and 4 absent. Print how many are present.','total = 30\nabsent = 4','total = 30\nabsent = 4\nprint(total - absent)','26']]),quiz:[q('What is a program?','A set of instructions',['A monitor','Only a game','A person'],'Programs describe work for computers to perform.'),q('What does an interpreter do?','Executes source instructions',['Designs monitors','Writes every program for you','Only saves pictures'],'Python processes source code and executes it.'),q('Who created Python?','Guido van Rossum',['Ada Lovelace','Dennis Ritchie','Brendan Eich'],'Guido van Rossum created Python; the first public release was in 1991.'),q('Which sequence models a bill?','Input → process → output',['Output → tea → input','Print → monitor → keyboard','No processing needed'],'Quantities enter, a total is calculated, then displayed.'),q('What is source code?','The program text you write',['Only the result','Computer hardware','An internet connection'],'Source is the human-readable program text.'),q('Can code run but produce the wrong result?','Yes, due to a logical mistake',['No, never','Only in JavaScript','Only without a computer'],'A valid instruction can still solve the wrong problem.'),q('Where is Python useful?','Automation and data analysis',['Only web styling','Only typing documents','Only changing screen brightness'],'Python is general purpose and useful in many fields.')]},
{id:1,title:'Your First Python Program',subtitle:'Make the computer say hello',story:'A classroom notice board communicates information. Your program needs a way to show a message too. print() is your first notice board.',objectives:['Display text, numbers and multiple values','Read punctuation and comments','Recognize syntax and indentation errors'],concepts:[['Say it with print()','print is a built-in function: an action you can call. Parentheses () hold the values passed to it. Quotes mark a string, which means text. print("Hello") displays Hello without the quote marks.'],['Numbers and strings','print(10) and print("10") look the same on screen, but one value is a number and the other is text. 10 + 20 calculates 30; "10" + "20" joins text into 1020. Commas separate multiple values; print places a space between them by default.'],['Statements and comments','A statement is an instruction. Usually write one per line. # begins a comment that Python ignores until the end of the line. Comments explain intent to human readers.'],['Read errors as clues','Python is case sensitive: Print is not print. Balance quotes and parentheses. Indentation is leading whitespace; at the top level do not add it randomly. Later, indented blocks will group instructions. An error reports where Python noticed a problem, which may start on the previous line.']],visual:['Source: print("Hello")','Python interpreter','Output: Hello'],examples:[ex('Your first message','print("Hello World")\nprint("Welcome to Python Lab")\nprint(10 + 20)','Hello World\nWelcome to Python Lab\n30','Quotes create strings; the unquoted expression 10 + 20 is calculated before printing.'),ex('A personal introduction','# This is a comment\nprint("My name is", "Ayaan")\nprint("Age:", 20)','My name is Ayaan\nAge: 20','A comma separates arguments and print inserts a space. The comment produces no output.')],mistake:{code:'Print("Hello")',fix:'print("Hello")',why:'Names are case sensitive. A NameError means Python could not find the name you used.'},application:'Print an order receipt, a welcome message, or a short personal introduction.',tasks:tasks(1,[['Hello, Python','Print Hello Python exactly.','# Start here','print("Hello Python")','Hello Python'],['Introduce yourself','Print My name is Ayaan and Age: 20 on separate lines.','# Use two print calls','print("My name is Ayaan")\nprint("Age:", 20)','My name is Ayaan\nAge: 20'],['Receipt total','Print Total: 150 using a calculation of 100 + 50.','# Calculate before printing','print("Total:", 100 + 50)','Total: 150']]),quiz:[q('What does print("Hello") display?','Hello',['"Hello"','print Hello','Nothing'],'Quotes delimit text; they are not part of this string.'),q('What does # begin outside a string?','A comment',['A loop','A number','An error every time'],'The rest of that line is ignored by Python.'),q('Which name is the built-in output function?','print',['Print','PRINT','outputText'],'Python distinguishes lowercase and uppercase names.'),q('What does print(10 + 20) show?','30',['1020','10 + 20','An empty line'],'Numeric addition is evaluated first.'),q('What does print("10" + "20") show?','1020',['30','10 20','A type error'],'Adding strings concatenates them.'),q('Why use parentheses in print()?','They contain the arguments to the call',['They create a comment','They always mean multiplication','They hide errors'],'Parentheses call a function with its arguments.'),q('What does print("Age", 20) show?','Age 20',['Age20','Age,20','"Age" 20'],'print separates arguments with a space by default.')]},
{id:2,title:'Variables and Values',subtitle:'Give your information a name',story:'A school register labels each student’s name, age, and marks. Instead of remembering scattered values, you use meaningful labels. Variables give your program these labels.',objectives:['Create and reassign names','Use clear variable naming','Calculate with stored values'],concepts:[['Labels for values','age = 20 assigns the name age to the integer object 20. Think of a labeled box at first, but a Python variable actually refers to an object. Two names can refer to the same object; assignment does not automatically copy an object.'],['Assignment and reassignment','The right side of = is evaluated first, then the name on the left is bound to the result. age = age + 1 uses the old value to calculate a new one. = assigns; it does not ask whether two values are equal.'],['Naming rules','Use letters, digits, and underscores, but do not start with a digit. Names are case sensitive. Avoid reserved keywords such as if. snake_case names like total_price are conventional; prefer descriptive names over x when meaning matters.'],['Dynamic typing and multiple assignment','Objects have types; a name can later refer to a different type: score = 10 followed by score = "ten" is allowed. name, age = "Ayaan", 20 unpacks two values into two names. a = b = 0 binds both names to the same integer object.']],visual:['name → "Ayaan"','age → 20','marks → 85'],examples:[ex('Student register','name = "Ayaan"\nage = 20\nmarks = 85\nprint(name)\nprint(age)\nprint(marks)','Ayaan\n20\n85','Each name refers to a value; print looks that value up.'),ex('Shopping bill','price, quantity = 50, 3\ntotal_price = price * quantity\ntotal_price = total_price - 10\nprint(total_price)','140','The bill is 150, then reassignment applies a ₹10 discount.')],mistake:{code:'2marks = 85\nprint(2marks)',fix:'marks_2 = 85\nprint(marks_2)',why:'A name cannot start with a digit. Use a descriptive name beginning with a letter or underscore.'},application:'Store student details or prices once and reuse them throughout a bill.',tasks:tasks(2,[['Label your age','Create age with value 20, then print it.','# Create a name','age = 20\nprint(age)','20'],['Birthday update','Start with age = 20, increase it by 1, and print it.','age = 20','age = 20\nage = age + 1\nprint(age)','21'],['Discounted bill','Three notebooks cost ₹40 each. Subtract a ₹15 discount and print the total.','price = 40\nquantity = 3\ndiscount = 15','price = 40\nquantity = 3\ndiscount = 15\nprint(price * quantity - discount)','105']]),quiz:[q('What does age = 20 do?','Binds age to the value 20',['Checks equality','Prints age','Creates a string named 20'],'Assignment connects a name to an object.'),q('Which variable name is valid?','student_marks',['2marks','student-marks','class'],'Letters and underscores are allowed; class is reserved.'),q('After x = 3 then x = x + 2, what is x?','5',['3','2','32'],'The old value 3 is used before reassignment.'),q('Can a Python name refer to a new type later?','Yes',['No','Only integers','Only with a special declaration'],'Python names can be rebound to objects of different types.'),q('What is the preferred style for total price?','total_price',['total-price','2total','total price'],'snake_case is conventional and descriptive.'),q('What does a, b = 2, 4 assign to b?','4',['2','6','A tuple of both numbers'],'Values unpack positionally into names.'),q('Is assignment always an object copy?','No, names refer to objects',['Yes, always','Only strings are copied','It deletes the old object immediately'],'Aliasing matters especially for mutable objects such as lists.')]},
{id:3,title:'Data Types & Conversion',subtitle:'Know what kind of value you have',story:'A price tag says “50”, but a calculator needs the number 50 to add costs. Text and numbers may look alike while behaving differently.',objectives:['Recognize int, float, str, bool and None','Inspect values with type()','Convert text to numbers and handle invalid conversions'],concepts:[['Kinds of values','int stores whole numbers like 5. float stores approximate fractional numbers like 2.5. str stores text. bool has True and False, with capitals. None is a special value meaning absence; its type is NoneType.'],['Inspect with type()','type(value) returns its type. A value and its type are different: 10 is an integer value; int is its type. Quotation marks make "10" a string even when it contains digits.'],['Convert deliberately','int("10") gives 10, float("2.5") gives 2.5, and str(10) gives "10". int(2.9) truncates toward zero to 2; it does not round. int("2.9") fails because that text is not an integer literal.'],['Errors tell you a mismatch','"10" + "20" joins strings; 10 + 20 adds integers. Mixing "10" + 20 raises TypeError. int("chai") raises ValueError: the kind of input is accepted, but its contents cannot represent an integer.']],visual:['"50" : str','int("50") : conversion','50 : int'],examples:[ex('Type detective','print(type(10))\nprint(type(2.5))\nprint(type("10"))\nprint(type(True))\nprint(type(None))',"<class 'int'>\n<class 'float'>\n<class 'str'>\n<class 'bool'>\n<class 'NoneType'>",'type reports the kind of each object, not its display style.'),ex('Text to a bill','price = "50"\nquantity = 3\nprint(int(price) * quantity)\nprint("10" + "20")','150\n1020','Converting price allows multiplication as a number. The last line joins two strings.')],mistake:{code:'print(int("2.5"))',fix:'print(float("2.5"))',why:'Text with a decimal point needs float(). Use int(float("2.5")) only if you deliberately want to discard the fraction.'},application:'Convert a text price from a form before calculating a shopping total.',tasks:tasks(3,[['Convert a price','Convert "50" to an integer and print it.','price = "50"','price = "50"\nprint(int(price))','50'],['Decimal total','Convert "12.5" to a float, multiply by 2, then print.','price = "12.5"','price = "12.5"\nprint(float(price) * 2)','25.0'],['Add text numbers','Convert "10" and "20" to numbers and print their sum.','a = "10"\nb = "20"','a = "10"\nb = "20"\nprint(int(a) + int(b))','30']]),quiz:[q('What is the type of "25"?','str',['int','float','bool'],'Quotes make the value text.'),q('What does int("12") return?','12',['"12"','12.0','None'],'Conversion creates an integer from valid integer text.'),q('What is the result of int(2.9)?','2',['3','2.9','An error'],'int truncates toward zero; it does not round.'),q('Which conversion fails?','int("chai")',['int("10")','float("2.5")','str(20)'],'chai does not represent an integer, so this raises ValueError.'),q('Which is a Boolean literal?','True',['"True"','true','NONE'],'Capitalization matters. "True" is a string.'),q('What does None represent?','An absent value',['Always zero','An empty string','False spelled differently'],'None is a distinct singleton used to represent absence.'),q('What happens with "10" + 20?','TypeError',['30','1020','None'],'Python does not implicitly convert the integer for string addition.')]},
{id:4,title:'Taking User Input',subtitle:'Turn a script into a conversation',story:'A shopkeeper asks how many notebooks you need before writing the bill. An interactive program also asks for information before calculating.',objectives:['Read responses with input()','Convert numeric input','Handle invalid user responses'],concepts:[['Ask with input()','input("Your name: ") displays a prompt and returns the response as a string, without the trailing newline. Store that result to use it later. In this lab, enter responses in the input queue before running, one per line.'],['Numbers arrive as text','Even if someone types 20, input() returns "20". Use int() for whole numbers or float() for decimal values before arithmetic. Prompts are output too; the queue supplies answers but does not echo them.'],['Input → process → output','Read quantities, calculate a result, and display it. Ask for clear units: a price in rupees or an age in years. A birth-year calculation gives the age reached during that year; exact age also depends on the birthday.'],['Handle incorrect input','try: starts a block that might fail. except ValueError: handles invalid numeric text. These blocks use indentation (usually four spaces). This first look at error handling helps your program respond politely instead of crashing. An empty input queue causes EOFError: supply another response.']],visual:['Input: "3"','Process: int("3") × 40','Output: ₹120'],examples:[ex('A personal greeting','name = input("Enter your name: ")\nprint("Hello", name)','Enter your name: Hello Ayaan','input returns the queued string. The prompt has no newline, so the greeting appears on the same line.','Ayaan'),ex('A helpful bill','try:\n    quantity = int(input("Quantity: "))\n    print("Total:", quantity * 40)\nexcept ValueError:\n    print("Please enter a whole number")','Quantity: Total: 120','int converts the response. Invalid text takes the except branch instead.','3'),ex('Age reached this year','year = int(input("Current year: "))\nborn = int(input("Birth year: "))\nprint("Age reached this year:", year - born)','Current year: Birth year: Age reached this year: 20','Subtract the birth year. This is the age reached during the given year, not necessarily the age today.','2026\n2006')],mistake:{code:'age = input("Age: ")\nprint(age + 1)',fix:'age = int(input("Age: "))\nprint(age + 1)',why:'input returns text. Convert before adding a number. Test with invalid input as well.'},application:'Collect names, bill quantities, and ages in a small interactive assistant.',tasks:tasks(4,[['Greet a visitor','Read one line without a prompt, and print Hello followed by their name. The check supplies Ayaan.','name = input()','name = input()\nprint("Hello", name)','Hello Ayaan'],['Next birthday','Read an integer age without a prompt and print age + 1. The check supplies 20.','age = input()','age = int(input())\nprint(age + 1)','21'],['Input bill','Read quantity without a prompt, then print the cost at ₹40 each. The check supplies 3.','quantity = input()','quantity = int(input())\nprint(quantity * 40)','120']]).map((t,i)=>({...t,input:['Ayaan','20','3'][i]})),quiz:[q('What type does input() return?','str',['int','float','bool'],'Input is text even when it looks numeric.'),q('How do you read a whole-number age?','int(input())',['input(int)','str(input())','print(input)'],'Convert the returned string using int.'),q('What can int("abc") raise?','ValueError',['No error','A Boolean','IndentationError'],'The text cannot represent a whole number.'),q('Where do you put responses in this lab?','In the input queue before running',['In the output panel','In the page title','In a terminal installation'],'One queue line answers one input call.'),q('What does except ValueError handle?','Invalid value conversion',['Every possible error','Only spelling mistakes','A missing quotation mark'],'It handles that specific exception type.'),q('Why can age + 1 fail after age = input()?','age is a string',['1 is too small','Python cannot add','input returns None'],'Convert the text into a number first.'),q('Does current year minus birth year always give exact age today?','No, the birthday matters',['Yes, always','Only in Python','Only for adults'],'It gives the age reached in that calendar year.')]},
{id:5,title:'Python Operators',subtitle:'Calculate, compare, and combine',story:'Splitting 17 sweets among 5 friends gives each friend 3 sweets with 2 left over. Python has an operator for both the share and the leftovers.',objectives:['Use arithmetic and assignment operators','Compare values and combine conditions','Distinguish equality, identity and membership'],concepts:[['Arithmetic','+ adds, - subtracts, * multiplies, / divides, ** raises to a power. // is floor division, rounding the quotient down: -7 // 2 is -4. % gives the remainder; for positive integers it finds leftovers or tests divisibility.'],['Assignment versus comparison','= assigns a name. += updates a value, such as total += 10. == compares equality; != means unequal. <, <=, >, >= compare order. Comparisons produce True or False.'],['Logic and membership','and requires both conditions to be true; or requires at least one. not reverses a truth value. in checks membership, such as "a" in "chai". not in checks absence. and/or actually return an operand; Boolean conditions are a simple first use.'],['Identity and precedence','== compares values; is checks whether two names refer to the same object. Use is None for absence, not is for ordinary numeric or text equality. Parentheses group calculations; powers come before multiplication/division, then addition/subtraction. Comparisons come before not, and, or.']],visual:['17 sweets ÷ 5 friends','17 // 5 → 3 each','17 % 5 → 2 left'],examples:[ex('Share and remainder','print(17 / 5)\nprint(17 // 5)\nprint(17 % 5)\nprint(2 + 3 * 4)','3.4\n3\n2\n14','Division returns 3.4, floor division 3, and remainder 2. Multiplication has precedence over addition.'),ex('Eligibility and identity','age = 20\nhas_id = True\nprint(age >= 18 and has_id)\na = [1]\nb = [1]\nprint(a == b)\nprint(a is b)\nprint("a" in "chai")','True\nTrue\nFalse\nTrue','The two lists contain equal values but are different objects. Membership looks for a value.')],mistake:{code:'age = 18\nprint(age = 18)',fix:'age = 18\nprint(age == 18)',why:'= is assignment, not an equality test. Inside this comparison expression use ==.'},application:'Calculate discounts, check age eligibility, and use number % 2 == 0 for even numbers.',tasks:tasks(5,[['Leftover sweets','Print the remainder when 17 is divided by 5.','# Use remainder','print(17 % 5)','2'],['Discount total','A ₹500 item has a 20% discount. Print the final price as a number.','price = 500\ndiscount = 20','price = 500\ndiscount = 20\nprint(price - price * discount / 100)','400.0'],['Even or odd','For number = 14, print Even if divisible by 2, otherwise Odd.','number = 14\n# Write your logic','number = 14\nif number % 2 == 0:\n    print("Even")\nelse:\n    print("Odd")','Even']]),quiz:[q('What does 17 % 5 produce?','2',['3','3.4','5'],'After making three groups of five, two remain.'),q('What does 7 // 2 produce?','3',['3.5','4','1'],'Floor division rounds the quotient down.'),q('Which operator compares values for equality?','==',['=','is always','+='],'== compares values; = assigns.'),q('What does True and False produce?','False',['True','None','A syntax error'],'Both must be truthy for a true Boolean result.'),q('What does 2 + 3 * 4 produce?','14',['20','24','9'],'Multiplication happens first.'),q('When should you use is?','To compare object identity',['To compare every number','To join strings','To assign names'],'Use == for value equality; is None is a common identity check.'),q('What does "x" not in "chai" return?','True',['False','None','x'],'The string chai has no x character.')]},
{id:6,title:'Making Decisions',subtitle:'Teach your program to choose',story:'At a traffic light, red means stop and green means go. You observe a condition and choose a branch. Programs make choices using the same pattern.',objectives:['Write if, elif and else blocks','Combine and nest conditions','Understand truthy and falsy values'],concepts:[['Choose a branch','if condition: runs its indented block when the condition is truthy. The colon begins the block. else: is the fallback. Use four spaces consistently; indentation is part of Python syntax, not decoration.'],['Several choices','elif means “otherwise, if”. Python checks conditions in order and runs only the first matching branch in an if/elif/else chain. Put grade thresholds from highest to lowest so a broad condition does not hide a more specific one.'],['Combine or nest','and combines requirements. You can nest an if inside another if, but keep the levels clear. For an ATM, require amount > 0 and amount <= balance before allowing a withdrawal. Real ATMs require much more security.'],['Truthy and falsy','False, None, numeric zero, and empty strings or collections are falsy. Many other values are truthy, including the nonempty string "False". When learning, explicit comparisons often communicate intent best.']],visual:['marks ≥ 40?','True → Pass','False → Try again'],examples:[ex('Pass or try again','marks = 72\nif marks >= 40:\n    print("Pass")\nelse:\n    print("Try again")','Pass','72 >= 40 is True, so only the first block runs.'),ex('Grade calculator','marks = 85\nif marks >= 90:\n    print("A")\nelif marks >= 75:\n    print("B")\nelse:\n    print("Keep practising")','B','85 misses the first condition but meets the second. The remaining branches are skipped.')],mistake:{code:'if 20 >= 18:\nprint("Eligible")',fix:'if 20 >= 18:\n    print("Eligible")',why:'The body of an if must be indented. The colon and indentation work together.'},application:'Build grade calculators, ticket eligibility checks, or a simplified ATM validation.',tasks:tasks(6,[['Eligibility','With age = 20, print Eligible if age is at least 18, otherwise Not yet.','age = 20','age = 20\nif age >= 18:\n    print("Eligible")\nelse:\n    print("Not yet")','Eligible'],['Grade bands','For marks = 85, print A at 90+, B at 75+, otherwise C.','marks = 85','marks = 85\nif marks >= 90:\n    print("A")\nelif marks >= 75:\n    print("B")\nelse:\n    print("C")','B'],['ATM check','For balance = 1000 and amount = 400, print Approved only if amount is positive and no more than balance; otherwise Declined.','balance = 1000\namount = 400','balance = 1000\namount = 400\nif amount > 0 and amount <= balance:\n    print("Approved")\nelse:\n    print("Declined")','Approved']]),quiz:[q('What follows an if condition before its block?',':',[';','{','then'],'The colon introduces the indented body.'),q('How many branches run in one if/elif/else chain?','At most one',['Always all','Exactly two','Only else'],'The first truthy branch wins; without else none may run.'),q('What is bool("")?','False',['True','None','An error'],'An empty string is falsy because it contains no characters. Nonempty strings are truthy.'),q('Why check marks >= 90 before marks >= 40?','The broader test would catch high marks first',['Python sorts tests','90 is a string','Order never matters'],'Checks are evaluated in the order written.'),q('What does else mean?','Run if no earlier branch matched',['Repeat forever','Always run','Define a function'],'else is a fallback branch.'),q('Is the string "False" truthy?','Yes',['No','Only sometimes','It is a bool'],'Any nonempty string is truthy, regardless of its text.'),q('How can two requirements both be required?','Use and',['Use or','Use =','Use print'],'and requires both Boolean conditions to be true.')]},
{id:7,title:'Loops & Repetition',subtitle:'Let Python do the repeating',story:'Calling out 30 student names one by one is repetitive. A loop repeats a small set of instructions for each student, saving you from writing the same code again.',objectives:['Repeat with for, while and range','Trace loop variables step by step','Use break and continue safely'],concepts:[['for and range()','for number in range(1, 4): visits 1, 2, and 3. The stop value is excluded. number is rebound to each value, and the indented body runs once per value. for can also visit items in a list or characters in a string.'],['while repeats a condition','while condition: repeats as long as the condition stays truthy. Update the state inside the loop so it can finish. If the condition never becomes false, it is an infinite loop. Use Stop in this lab; a 12-second execution limit also restarts the worker.'],['break and continue','break exits the innermost loop immediately. continue skips the rest of the current iteration and moves to the next one. In while loops, make sure an update is not accidentally skipped by continue.'],['Nested loops','A loop inside a loop is nested. For each outer iteration, the inner loop runs completely. Two rows and three columns produce six pairs. Keep nesting small and trace it slowly.']],visual:['range(1, 4)','number = 1 → body','number = 2 → body','number = 3 → body → stop'],examples:[ex('A multiplication table','for number in range(1, 6):\n    print(3, "x", number, "=", 3 * number)','3 x 1 = 3\n3 x 2 = 6\n3 x 3 = 9\n3 x 4 = 12\n3 x 5 = 15','range excludes 6, so the loop runs five times.'),ex('Count down safely','remaining = 3\nwhile remaining > 0:\n    print(remaining)\n    remaining -= 1\nprint("Go!")','3\n2\n1\nGo!','Each iteration reduces remaining; when it reaches zero, the condition is false.'),ex('Skip and stop','for n in range(1, 8):\n    if n == 2:\n        continue\n    if n == 5:\n        break\n    print(n)','1\n3\n4','2 is skipped and reaching 5 exits the loop before printing it.')],mistake:{code:'n = 1\nwhile n <= 3:\n    print(n)',fix:'n = 1\nwhile n <= 3:\n    print(n)\n    n += 1',why:'Without updating n, the condition stays true. Stop the run and add the update.'},application:'Count attendance, generate tables, add a series, or limit password retries.',tasks:tasks(7,[['Count to three','Print 1, 2, 3 on separate lines using a loop.','# Use range','for n in range(1, 4):\n    print(n)','1\n2\n3'],['Sum a series','Use a loop to add numbers 1 through 5 and print only the total.','total = 0','total = 0\nfor n in range(1, 6):\n    total += n\nprint(total)','15'],['Skip an absence','Print student numbers 1 through 5, except 3, each on a new line.','# Use continue','for n in range(1, 6):\n    if n == 3:\n        continue\n    print(n)','1\n2\n4\n5']]),quiz:[q('Which values does range(1, 4) visit?','1, 2, 3',['1, 2, 3, 4','0, 1, 2, 3','Only 4'],'The stop bound is excluded.'),q('What does break do?','Exits the innermost loop',['Skips only one print','Restarts the program','Ends every function'],'break leaves its loop immediately.'),q('What does continue do?','Skips the rest of the current iteration',['Exits the loop','Pauses forever','Defines a variable'],'The loop proceeds to its next iteration.'),q('Why update a counter in a while loop?','So its condition can eventually become false',['To change the language','For decoration','Python requires every loop to count'],'State must change when termination depends on it.'),q('Two outer iterations and three inner iterations produce how many body runs?','6',['2','3','5'],'The inner body runs three times for each of two outer visits.'),q('What is an infinite loop?','A loop whose stopping condition is never reached',['Any for loop','A syntax error','A loop with three repetitions'],'It can keep consuming resources until stopped.'),q('How do you recover from a stuck run here?','Use Stop to terminate the worker',['Close all applications','Wait forever','Delete your source code'],'Worker termination keeps the page responsive.')]},
{id:8,title:'Working With Strings',subtitle:'Make text work for you',story:'A school prints certificates with neatly formatted names. Names arrive with extra spaces or inconsistent capitals. String tools help clean and format them.',objectives:['Index and slice text','Format messages with f-strings','Use methods while respecting immutability'],concepts:[['Indexes and slices','Indexes start at zero: "Python"[0] is "P". -1 means the last character. text[start:stop] includes start but excludes stop. An out-of-range single index raises IndexError; slices safely stop at the end.'],['Useful methods','len(text) counts characters. strip() removes whitespace at both ends. lower(), upper(), and title() change case in a new string. replace(old, new) returns substituted text. split() makes a list of words; separator.join(words) joins them.'],['Formatted messages','+ concatenates strings. f"Hello {name}" inserts an expression inside braces {}. f"{price:.2f}" formats a number to two decimal places. The f prefix must be directly before the opening quote.'],['Text is immutable','You cannot assign to an individual string position. Methods produce new strings; assign the result to keep it. These examples use simple Latin text; some visible characters in other writing systems can consist of multiple Unicode code points.']],visual:['P [0]','y [1]','t [2]','h [3]','o [4]','n [5 / -1]'],examples:[ex('A clean name','name = "  ayaan khan  "\nname = name.strip().title()\nprint(f"Hello, {name}!")\nprint(len(name))','Hello, Ayaan Khan!\n10','strip removes surrounding spaces and title returns title-cased text. The internal space counts toward length.'),ex('Mask a phone number','phone = "9876543210"\nprint("******" + phone[-4:])\nprint("Python"[0:3])','******3210\nPyt','A negative slice starts four characters from the end. The stop index 3 is excluded.')],mistake:{code:'name = "Ayaan"\nname[0] = "a"',fix:'name = "Ayaan"\nname = "a" + name[1:]\nprint(name)',why:'Strings cannot be edited in place. Build a new string and reassign the name.'},application:'Clean names, format currency messages, and mask personal details in displayed text.',tasks:tasks(8,[['First character','Print the first character of Python.','word = "Python"','word = "Python"\nprint(word[0])','P'],['Clean a name','Remove outside spaces and title-case "  ayaan khan  ", then print.','name = "  ayaan khan  "','name = "  ayaan khan  "\nprint(name.strip().title())','Ayaan Khan'],['Format a bill','Print Total: ₹125.50 from total = 125.5 using two decimal places.','total = 125.5','total = 125.5\nprint(f"Total: ₹{total:.2f}")','Total: ₹125.50']]),quiz:[q('What does "Python"[0] return?','P',['y','n','Python'],'Indexing starts at zero, so index 0 selects the first character, P.'),q('What does "Python"[-1] return?','n',['P','o','An empty string'],'-1 refers to the last character.'),q('What does "Python"[0:2] return?','Py',['Pyt','yt','Python'],'A slice excludes its stop position.'),q('Can you assign to word[0] for a string?','No, strings are immutable',['Yes, always','Only uppercase letters','Only after strip()'],'Create a new string instead.'),q('Which removes whitespace at both ends?','strip()',['split()','len()','append()'],'strip returns a new string with surrounding whitespace removed.'),q('What is f"Hi {name}" used for?','Inserting a value into text',['Defining a function','Creating a comment','Changing a list'],'An f-string evaluates expressions in braces.'),q('What does len("Hi there") return?','8',['7','2','9'],'Spaces count as characters too.')]},
{id:9,title:'Lists & Tuples',subtitle:'Keep related values together',story:'A shopping list grows as you remember more items. A location’s fixed coordinates are different: you usually treat the pair as a single fixed record. Lists and tuples model these situations.',objectives:['Create, index, update and slice lists','Add and remove items','Choose between mutable lists and immutable tuples'],concepts:[['Lists hold a sequence','Use square brackets: marks = [80, 90, 75]. Commas separate items. marks[0] is 80; marks[-1] is 75. len(marks) counts items and marks[1:3] takes a slice. Lists preserve order and can contain mixed types, though consistent types are often easier to use.'],['Change the list','marks[0] = 85 replaces an item. append(value) adds one item at the end. remove(value) removes the first matching value and raises ValueError if missing. pop() removes and returns the last item; pop(index) removes at that index.'],['Visit and calculate','for mark in marks: visits values. sum(marks) adds numeric items. A simple average is sum(marks) / len(marks); check the list is nonempty first to avoid division by zero.'],['Tuples and shared references','point = (3, 4) is a tuple. Tuple item references cannot be replaced; a one-item tuple needs a trailing comma, (3,). Lists are mutable. b = a aliases a list, while a.copy() makes a shallow copy. A tuple can still contain a mutable object, so immutability does not freeze all nested contents.']],visual:['marks[0] → 80','marks[1] → 90','marks[2] → 75'],examples:[ex('Shopping list','items = ["milk", "tea"]\nitems.append("sugar")\nitems.remove("tea")\nprint(items)\nprint(items.pop())',"['milk', 'sugar']\nsugar",'append adds sugar; remove finds tea by value; pop returns the final item.'),ex('Marks manager','marks = [80, 90, 70]\nmarks[0] = 85\nfor mark in marks:\n    print(mark)\nprint("Average:", sum(marks) / len(marks))','85\n90\n70\nAverage: 81.66666666666667','The first item changes to 85. The average divides the total 245 by three.')],mistake:{code:'point = (3, 4)\npoint[0] = 5',fix:'point = (3, 4)\npoint = (5, point[1])\nprint(point)',why:'A tuple cannot have an item replaced. Create another tuple or choose a list for editable values.'},application:'Store marks or shopping items in lists; use tuples for fixed records such as coordinate pairs.',tasks:tasks(9,[['First mark','Print the first value from [80, 90, 70].','marks = [80, 90, 70]','marks = [80, 90, 70]\nprint(marks[0])','80'],['Extend a list','Append 100 to [80, 90] and print the list.','marks = [80, 90]','marks = [80, 90]\nmarks.append(100)\nprint(marks)','[80, 90, 100]'],['Average marks','Print the average of [80, 90, 70] with one decimal place.','marks = [80, 90, 70]','marks = [80, 90, 70]\nprint(f"{sum(marks) / len(marks):.1f}")','80.0']]),quiz:[q('Which creates a list?','[1, 2]',['(1, 2)','{1, 2}','"1, 2"'],'Square brackets create list literals.'),q('What does append() do?','Adds one item at the end',['Removes the first item','Sorts every list','Returns a new tuple'],'append changes the list in place.'),q('What does pop() return?','The removed last item',['Always None','The full list','The first index'],'With no index, pop removes and returns the last item.'),q('What does remove(5) remove?','The first item equal to 5',['The item at index 5','All items','The last five items'],'remove searches by value, not index.'),q('Can tuple items be reassigned?','No',['Yes','Only numbers','Only the last item'],'Tuple item references are immutable.'),q('After b = a for a list, do they refer to the same list?','Yes',['No, a deep copy is made','Only when empty','Only for tuples'],'Assignment creates another reference, not a new list.'),q('What should you check before dividing by len(marks)?','That the list is nonempty',['That it is a string','That it has exactly ten items','Nothing'],'An empty list has length zero.')]},
{id:10,title:'Dictionaries & Sets',subtitle:'Connect information and find unique values',story:'A contact book connects each person’s name to a phone number. A class attendance list may contain repeated IDs, but you need to count each student once.',objectives:['Read and update key-value pairs','Iterate through dictionary items','Remove duplicates and choose a collection'],concepts:[['Dictionaries connect keys to values','contacts = {"Ayaan": "1234"} uses braces, a colon between key and value, and commas between pairs. contacts["Ayaan"] looks up the value. Keys must be hashable (for example strings, numbers or tuples of hashable values); each key is unique.'],['Read and update safely','contacts["Sara"] = "5678" adds or updates a key. get("Missing", "Unknown") supplies a fallback rather than raising KeyError. keys(), values(), and items() provide views of the contents. pop(key) removes and returns a value.'],['Iterate over pairs','for name, phone in contacts.items(): unpacks each pair. Dictionaries preserve insertion order. Using the same key again updates its value; it does not add a duplicate key.'],['Sets and collection choices','set([1, 1, 2]) contains unique values. Sets are unordered collections of hashable items; do not rely on print order. Use set() for an empty set because {} is an empty dictionary. Use a list for ordered editable sequences, tuple for fixed records, dictionary for lookup by key, set for uniqueness and membership.']],visual:['"Ayaan" → "1234"','"Sara" → "5678"','IDs [1, 1, 2] → set {1, 2}'],examples:[ex('Contact book','contacts = {"Ayaan": "1234"}\ncontacts["Sara"] = "5678"\nfor name, phone in contacts.items():\n    print(name, phone)\nprint(contacts.get("Ali", "Unknown"))','Ayaan 1234\nSara 5678\nUnknown','items yields key-value pairs. get returns the fallback for a missing key.'),ex('Unique attendance','ids = [101, 102, 101, 103]\nunique_ids = set(ids)\nprint(len(unique_ids))\nprint(102 in unique_ids)','3\nTrue','Repeated 101 collapses into one set member. Membership returns a Boolean.')],mistake:{code:'contacts = {"Ayaan": "1234"}\nprint(contacts["Ali"])',fix:'contacts = {"Ayaan": "1234"}\nprint(contacts.get("Ali", "Unknown"))',why:'Direct indexing with a missing key raises KeyError. get is useful when missing keys are expected.'},application:'Manage product inventory with dictionaries and unique student IDs with sets.',tasks:tasks(10,[['Find a contact','Print the phone value for Ayaan.','contacts = {"Ayaan": "1234"}','contacts = {"Ayaan": "1234"}\nprint(contacts["Ayaan"])','1234'],['Count unique IDs','Print how many unique values are in [1, 2, 1, 3, 2].','ids = [1, 2, 1, 3, 2]','ids = [1, 2, 1, 3, 2]\nprint(len(set(ids)))','3'],['Inventory update','Starting with 10 notebooks, sell 3 and print the remaining notebook stock.','stock = {"notebooks": 10}','stock = {"notebooks": 10}\nstock["notebooks"] -= 3\nprint(stock["notebooks"])','7']]),quiz:[q('What structure stores key-value pairs?','dict',['list','tuple','str'],'Dictionaries map keys to values.'),q('What does {} create?','An empty dictionary',['An empty set','A tuple','A list'],'Use set() for an empty set.'),q('What happens when an existing dictionary key is assigned again?','Its value is updated',['A duplicate key is added','Always an error','The dictionary is sorted'],'Dictionary keys are unique.'),q('Which method yields key-value pairs?','items()',['append()','lower()','split()'],'items provides pairs that can be unpacked in a loop.'),q('What does set([1, 1, 2]) contain?','Two unique values',['Three unique values','Only 1','A key and a value'],'Sets eliminate duplicate members.'),q('Can you rely on set iteration order?','No',['Yes, always alphabetical','Yes, insertion order','Only for phone numbers'],'Sets have no guaranteed positional order.'),q('How can a missing dictionary key have a fallback?','Use get(key, fallback)',['Use append','Use index zero','Use strip'],'get avoids KeyError for an expected missing key.')]},
{id:11,title:'Functions & Reusable Code',subtitle:'Write a recipe once. Use it again.',story:'A vending machine accepts a selection and returns a snack. You do not rebuild the machine for each order. A function packages reusable instructions with inputs and a result.',objectives:['Define and call functions','Use parameters, arguments and defaults','Distinguish returning from printing and understand scope'],concepts:[['Define a recipe','def add(a, b): defines a function named add. a and b are parameters, names for incoming values. The colon introduces an indented body. Defining a function does not run its body; calling add(2, 3) runs it with arguments 2 and 3.'],['Return a result','return sends a value to the caller and ends the function call. print displays a value but does not substitute for returning it. A function that reaches its end without return returns None. Keep calculations separate from display so they can be reused.'],['Default arguments','def greet(name="friend"): allows greet() as well as greet("Ayaan"). Required parameters must precede default parameters. Defaults are evaluated when the function is defined; avoid mutable list/dictionary defaults for accumulating user data.'],['Local and global names','A name assigned inside a function is normally local to that call. Names defined at the module level are global. Reading a global is possible, but passing inputs and returning outputs is usually easier to test. Assignment inside does not normally change a same-named global.']],visual:['Arguments: 2, 3','Function: add(a, b)','Return value: 5'],examples:[ex('A reusable calculator','def add(a, b):\n    return a + b\n\nresult = add(2, 3)\nprint(result)\nprint(add(10, 20))','5\n30','return hands a number back to the caller; the caller decides to print it.'),ex('Defaults and local scope','name = "class"\ndef greet(name="friend"):\n    return f"Hello {name}"\n\nprint(greet())\nprint(greet("Ayaan"))\nprint(name)','Hello friend\nHello Ayaan\nclass','The local parameter name does not overwrite the global name.')],mistake:{code:'def add(a, b):\n    print(a + b)\n\nprint(add(2, 3))',fix:'def add(a, b):\n    return a + b\n\nprint(add(2, 3))',why:'The broken version prints 5 inside the function, then prints None because the function returned no explicit result.'},application:'Write separate calculator functions and reuse the same billing logic for many customers.',tasks:tasks(11,[['Return a square','Define square(n) returning n * n. Do not just print the result.','def square(n):\n    pass','def square(n):\n    return n * n','', 'assert square(3) == 9\nassert square(-4) == 16\nassert square(0) == 0'],['Reusable addition','Define add(a, b) returning their sum.','def add(a, b):\n    pass','def add(a, b):\n    return a + b','', 'assert add(2, 3) == 5\nassert add(-2, 2) == 0\nassert add(1.5, 2.5) == 4'],['Bill function','Define bill(price, quantity=1) returning price times quantity.','def bill(price, quantity=1):\n    pass','def bill(price, quantity=1):\n    return price * quantity','', 'assert bill(40) == 40\nassert bill(40, 3) == 120\nassert bill(0, 5) == 0']]),quiz:[q('Which keyword defines a function?','def',['function','func','define'],'def introduces a function definition.'),q('Does defining a function immediately execute its body?','No',['Yes','Only with return','Only with numbers'],'The body runs when the function is called.'),q('What are parameters?','Names for values received by a function',['Only printed output','Global variables always','Comments'],'Arguments are the supplied values; parameters receive them.'),q('What does return do?','Sends a value to the caller',['Always prints a message','Starts a loop','Creates input'],'return also ends the current function call.'),q('What is returned without an explicit return value?','None',['0','An empty string','The last printed number'],'Python implicitly returns None at the end.'),q('Where is a locally assigned name normally available?','Inside that function call',['Everywhere forever','Only in the editor','In all browsers'],'Local scope prevents accidental name clashes.'),q('What does def greet(name="friend") allow?','Calling greet() without an argument',['Only calling greet("friend")','No function calls','A syntax error'],'The default supplies a value when no argument is passed.')]},
{id:12,title:'Your First Mini-Projects',subtitle:'Bring your Python skills together',story:'You now have a toolbox. A real project combines its tools: ask for information, organize it, choose what to do, repeat work, and communicate the result.',objectives:['Build a grade calculator','Model expenses using lists and dictionaries','Create a bounded number guessing game'],concepts:[['Plan before typing','Write input, process, and output for each project. Break the process into small steps and implement one at a time. First get a simple working case, then add validation and better messages.'],['Student grades','Read marks, convert to numbers, check 0–100, then select a grade in descending threshold order. Test at boundaries such as 39/40 and 74/75; checking only an average score misses common bugs.'],['Expense tracking','Use a list of dictionaries: each record has a name and an amount. Iterate to calculate a total. This browser runtime keeps Python memory only for a run; app snippets and completion use localStorage, but Python variables do not persist across runs.'],['Guessing and revision','random.randint(1, 10) includes both endpoints. Compare guesses against a target, give feedback, and limit attempts with a loop. Use a fixed target first to make testing repeatable, then add randomness. Combine small functions when logic repeats.']],visual:['Plan → small steps','Build → run → inspect','Test boundaries → improve'],examples:[ex('Grade calculator','marks = int(input())\nif not 0 <= marks <= 100:\n    print("Invalid marks")\nelif marks >= 75:\n    print("Distinction")\nelif marks >= 40:\n    print("Pass")\nelse:\n    print("Try again")','Distinction','85 is valid and meets the highest threshold. Try 40, 39, 100, and 101.','85'),ex('Expense tracker','expenses = [{"name": "Tea", "amount": 20}, {"name": "Bus", "amount": 30}]\ntotal = 0\nfor expense in expenses:\n    total += expense["amount"]\nprint("Total:", total)','Total: 50','Each dictionary represents a record. The accumulator combines their amounts.'),ex('A testable guessing game','target = 7\nfor attempt in range(3):\n    guess = int(input())\n    if guess == target:\n        print("Correct!")\n        break\n    print("Too low" if guess < target else "Too high")\nelse:\n    print("Out of attempts")','Too low\nCorrect!','The loop permits three attempts and break exits on success. The loop else runs only if no break occurred.','3\n7')],mistake:{code:'marks = 105\nif marks >= 40:\n    print("Pass")',fix:'marks = 105\nif not 0 <= marks <= 100:\n    print("Invalid marks")\nelif marks >= 40:\n    print("Pass")',why:'A result can be syntactically correct but accept invalid data. Validate the range before grading.'},application:'Build the three guided capstone projects in Projects, then take the mixed V1 revision assessment.',tasks:tasks(12,[['Grade boundaries','Define grade(marks) returning Invalid outside 0–100, Pass at 40+, otherwise Retry.','def grade(marks):\n    pass','def grade(marks):\n    if not 0 <= marks <= 100:\n        return "Invalid"\n    return "Pass" if marks >= 40 else "Retry"','', 'assert grade(40) == "Pass"\nassert grade(39) == "Retry"\nassert grade(101) == "Invalid"\nassert grade(-1) == "Invalid"'],['Expense total','Define total_expenses(expenses) returning the sum of all amount values in a list of dictionaries.','def total_expenses(expenses):\n    pass','def total_expenses(expenses):\n    total = 0\n    for expense in expenses:\n        total += expense["amount"]\n    return total','', 'assert total_expenses([]) == 0\nassert total_expenses([{"amount": 20}, {"amount": 30}]) == 50'],['Guess feedback','Define feedback(guess, target) returning Correct, Too low, or Too high.','def feedback(guess, target):\n    pass','def feedback(guess, target):\n    if guess == target:\n        return "Correct"\n    return "Too low" if guess < target else "Too high"','', 'assert feedback(7, 7) == "Correct"\nassert feedback(3, 7) == "Too low"\nassert feedback(9, 7) == "Too high"']]),quiz:[q('Why plan input, process and output first?','To break a problem into manageable steps',['To avoid all testing','To write longer code','Because Python requires a plan file'],'A plan clarifies what each part must do.'),q('Which grade tests are especially useful?','Boundary values such as 39 and 40',['Only 50','Only a student name','No tests'],'Neighboring values uncover comparison mistakes.'),q('Which suits a collection of named expense records?','A list of dictionaries',['Only a Boolean','A single integer','A comment'],'A list orders records; dictionaries label each field.'),q('Does random.randint(1, 10) include 10?','Yes',['No','Only when called twice','It returns text'],'Both endpoints are included.'),q('How can you make a guessing game repeatable for testing?','Use a fixed target',['Delete comparisons','Always accept every guess','Remove the loop'],'A fixed target makes expected feedback predictable.'),q('Do Python variables survive between runs in this lab?','No, each run has fresh globals',['Yes, forever','Only lists','Only when printed'],'Snippet code persists separately if saved; runtime variables are isolated per run.'),q('What is a useful next step after a project works once?','Test invalid inputs and boundaries',['Assume it is perfect','Delete the requirements','Add a database immediately'],'Verification includes ordinary cases, edges, and mistakes.')]}
];
export {chapters};
export const allTasks=chapters.flatMap(c=>c.tasks);
export const revisionQuiz=chapters.flatMap(c=>[c.quiz[0],c.quiz[5]]);
export const glossary=[['Argument','A value supplied when calling a function.'],['Assignment','Binding a name to an object with =.'],['Boolean','A value that is True or False.'],['Bug','A mistake causing incorrect behavior.'],['Dictionary','A collection of key-value pairs.'],['Expression','Code evaluated to produce a value, such as 2 + 3.'],['Function','A reusable block of instructions called by name.'],['Immutable','Unable to have its contents changed in place.'],['Indentation','Leading whitespace that defines Python blocks.'],['Index','A position in a sequence, starting at zero.'],['Interpreter','Software that processes and executes Python instructions.'],['Iteration','One visit through a repeating loop.'],['List','An ordered, mutable collection.'],['Local scope','The names available inside a particular function call.'],['Object','A Python value with identity, type, and contents.'],['Parameter','A name receiving an argument in a function definition.'],['Return','Send a value back to a function caller.'],['Set','An unordered collection of unique hashable values.'],['Source code','The human-readable instructions of a program.'],['Statement','An instruction, such as assignment or an if statement.'],['String','A sequence of text characters.'],['Syntax','Rules for writing code in a language.'],['Tuple','An ordered collection whose item references cannot be replaced.'],['Variable','A name referring to an object.']];
